import Vue, { defineComponent } from 'vue';
import Axios from 'axios';
import { default as ContentBlock } from './components/ContentBlock.vue';
import { default as ContentLine } from './components/ContentLine.vue';
import { formatCurrency } from '@game-studio/utilities';
import { inversifyContainer } from '../../../../inversify/container';
import { device } from '../../../../services/device';
// import { IHostRequestAdapter } from '../../../../frame-connection/host-request-adapter';
import { getLocaleString } from '../../../../services/utilities';

let dateFormat: string;

export interface IWinnerResponse {
    gameName: string;
    prize: number;
    prizeAsPence: number;
    stamp: string;
    userName: string;
}

Vue.filter('formatLocaleCurrency', (value: number): string => {
    return formatCurrency(value, inversifyContainer.currencySettings, false);
});

Vue.filter('convertToDate', (value: string): string => {
    return new Date(value).toLocaleString(dateFormat, {
        day: '2-digit',
        month: 'short',
        year: '2-digit',
        hour: '2-digit',
        minute: '2-digit'
    });
});

export default defineComponent({
    name: 'RecentWinners',
    components: {
        ContentBlock,
        ContentLine
    },
    props: {
        // internationalApiClient: { type: Object as PropType<IHostRequestAdapter>, required: false },
        apiUrl: { type: String, required: true },
        country: { type: String, default: 'uk', required: true },
        locale: { type: Object, required: true }
    },
    data() {
        return {
            initialLimit: 25,
            maximumLimit: 50,
            limit: 25,
            displayGameName: false,
            winners: [],
        };
    },
    computed: {
        currencySettings() {
            return inversifyContainer.currencySettings;
        },
        winnersFiltered(): IWinnerResponse[] {
            return this.winners.slice(0, this.limit);
        },
        showButton(): boolean {
            return this.winners.length > this.limit;
        }
    },
    mounted() {
        dateFormat = getLocaleString();
        if (this.country === 'uk' || this.country === void (0)) {
            this.displayGameName = this.isDesktop();
        }

        // const apiClient = this.internationalApiClient ?? Axios;
        const apiClient = Axios;

        apiClient.get(this.apiUrl)
            .then((response: any) => {
                return this.winners = response.data.winners || [];
            })
            .catch((error: any) => {
                throw new Error(error);
            });
    },
    methods: {
        isDesktop(): boolean {
            return device.type.isDesktop;
        },
        onViewMoreClick(): void {
            this.limit = this.maximumLimit;
        }
    }
});